-- Generated by scripts/build_seed_migration.py from data/places.json.
-- Missing records are retired, preserving their visit history if later restored.
UPDATE places SET active = FALSE;

ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name, category = EXCLUDED.category,
    latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude,
    region = EXCLUDED.region, description = EXCLUDED.description,
    source_url = EXCLUDED.source_url, source_name = EXCLUDED.source_name,
    source_id = EXCLUDED.source_id, active = TRUE;
